mapper.select:
select lmt.LITIGATION_MANAGEMENT_ID, lmt.PROJECT_ID, lmt.CONTRACT_NUMBER, lmt.CONTRACT_NUMBER as CONTRACT_NUMBER_N, lmt.TENANT_ID, ( SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = lmt.tenant_id ) tenant_id_n, lmt.HOST_PROJECT_MANAGER, ( SELECT s.description FROM sys_user s WHERE s.user_id = lmt.host_project_manager ) host_project_manager_n, lmt.CONTRACT_AMOUNT, lmt.LITIGATION_AMOUNT, lmt.HANDLE_WAY, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'AVS.HANDLE_WAY' AND lmt.HANDLE_WAY = v.CODE_VALUE )HANDLE_WAY_N,
lmt.DESCRIPTION, lmt.LITIGATION_RELEVANT_AMOUNT, lmt.HANDLE_DATE, lmt.STATUS, lmt.BP_ID, ( select hbm.bp_name from hls_bp_master hbm where hbm.BP_ID = lmt.BP_ID )BP_ID_N, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS.WFL_FUNDING_STATUS' AND lmt.STATUS = v.CODE_VALUE )STATUS_N, (select wm_concat(fa.file_name) from fnd_atm_attachment fa, fnd_atm_attachment_multi fam where fa.attachment_id = fam.attachment_id and fam.table_name = 'litigation_management' and lmt.LITIGATION_MANAGEMENT_ID = fam.table_pk_value) FILE_NAME
from litigation_management lmt ,prj_project pp
lmt.PROJECT_ID = pp.PROJECT_ID
and (pp.created_by = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
and lmt.CONTRACT_NUMBER = #{contractNumber}
and lmt.HOST_PROJECT_MANAGER = #{hostProjectManager}
and lmt.BP_ID = #{bpId}
and lmt.LITIGATION_MANAGEMENT_ID = #{litigationManagementId}
and lmt.HANDLE_DATE between #{handleDateFrom} and #{handleDateTo}
ORDER BY lmt.LITIGATION_MANAGEMENT_ID desc
